mapper.select:
SELECT a.OperatorID AS operatorId, a.ShiftID AS shiftId, a.TeamID AS teamId, IFNULL(SUM(TotalToll / 100), 0) as statAmount, IFNULL(SUM(CASE WHEN DealStatus&14=6 THEN CarNum ELSE 0 END),0) as officialIcCardCount, IFNULL(SUM(CASE WHEN DealStatus&14=8 THEN CarNum ELSE 0 END),0) as militaryIcCardCount, IFNULL(SUM(CASE WHEN DealStatus&14=12 THEN CarNum ELSE 0 END),0) as freeIcCardCount, IFNULL(SUM(CASE WHEN (DealStatus&14!=14 AND DealStatus&14!=2 AND DealStatus&0xE00000!=0x200000 AND DealStatus&0x1000000=0 AND DealStatus&32!=32 AND CardType=0) OR (CardType=26 AND DealStatus&32!=32) THEN CardNum ELSE 0 END),0) as dueIcCardCount, IFNULL(SUM(CASE WHEN DealStatus&14=4 THEN TotalArrearage ELSE 0 END),0)/100 arrearsAmount, SUM(CASE WHEN a.PayType = 0 THEN a.TotalToll / 100 ELSE 0 END) AS dueAmount, IFNULL(SUM(CASE WHEN DealStatus&14=4 THEN CarNum ELSE 0 END),0) arrearsTrips, IFNULL(CAST(SUM(CASE WHEN PayType=16 THEN TotalToll ELSE 0 END)/100 as DECIMAL(10,2)), 0) mobilePaymentAmount, IFNULL(CAST(SUM(CASE WHEN PayType=2 THEN TotalToll ELSE 0 END) /100 as DECIMAL(10,2)), 0) as ePaymentAmount FROM `tbstatexit` a
AND StationID in
#{stationId}
AND a.StaDate = #{timeFormat}
AND a.ShiftID = #{shiftId}
AND CancelFlag = 0 AND RecordType&1 =1
GROUP BY OperatorID ORDER BY OperatorID ASC

SELECT a.OperatorID AS operatorId, a.ShiftID AS shiftId, a.TeamID AS teamId, IFNULL(SUM(TotalToll / 100), 0) as statAmount, IFNULL(SUM(CASE WHEN DealStatus&14=6 THEN CarNum ELSE 0 END),0) as officialIcCardCount, IFNULL(SUM(CASE WHEN DealStatus&14=8 THEN CarNum ELSE 0 END),0) as militaryIcCardCount, IFNULL(SUM(CASE WHEN DealStatus&14=12 THEN CarNum ELSE 0 END),0) as freeIcCardCount, IFNULL(SUM(CASE WHEN (DealStatus&14!=14 AND DealStatus&14!=2 AND DealStatus&0xE00000!=0x200000 AND DealStatus&0x1000000=0 AND DealStatus&32!=32 AND CardType=0) OR (CardType=26 AND DealStatus&32!=32) THEN CardNum ELSE 0 END),0) as dueIcCardCount, IFNULL(SUM(CASE WHEN DealStatus&14=4 THEN TotalArrearage ELSE 0 END),0)/100 arrearsAmount, SUM(CASE WHEN a.PayType = 0 THEN a.TotalToll / 100 ELSE 0 END) AS dueAmount, IFNULL(SUM(CASE WHEN DealStatus&14=4 THEN CarNum ELSE 0 END),0) arrearsTrips, IFNULL(CAST(SUM(CASE WHEN PayType=16 THEN TotalToll ELSE 0 END)/100 as DECIMAL(10,2)), 0) mobilePaymentAmount, IFNULL(CAST(SUM(CASE WHEN PayType=2 THEN TotalToll ELSE 0 END) /100 as DECIMAL(10,2)), 0) as ePaymentAmount FROM `tbstatexit` a
AND StationID in
#{stationId}
AND a.StaDate = #{timeFormat}
AND a.ShiftID = #{shiftId}
AND CancelFlag = 0 AND RecordType &1 =1
GROUP BY OperatorID ORDER BY ShiftID ASC, OperatorID ASC

SELECT a.OperatorID AS operatorId, a.ShiftID AS shiftId, IFNULL(AddedToll/100,0) as addedToll, IFNULL(CAST(HandToll/100 as DECIMAL(10,2)), 0) as handToll FROM `tbsh` a
AND a.StationID in
#{stationId}
AND a.StaDate = #{timeFormat}
AND a.ShiftID = #{shiftId}
GROUP BY OperatorID

SELECT IFNULL(AddedToll/100,0) as addedToll, IFNULL(CAST(HandToll/100 as DECIMAL(10,2)), 0) as handToll, a.StaDate AS staDate, LEFT(a.StaDate, 6) AS monthDate, a.StationID AS stationId, a.OperatorID AS operatorId FROM
SELECT * FROM ${tableName}
AND StationID in
#{stationId}
AND StaDate >= #{intBeginTime}
AND StaDate <= #{intEndTime}
a
GROUP BY StaDate
GROUP BY monthDate
GROUP BY StationID
GROUP BY OperatorID

SELECT a.OperatorID AS operatorId, (SELECT OperatorName FROM dbtoms.tboperatorinfo WHERE a.OperatorID = OperatorID LIMIT 1 ) AS operatorName, IFNULL(SUM(CASE WHEN a.CardType=26 THEN 1 ELSE 0 END),0) AS yfIcCardNum, IFNULL(SUM(CASE WHEN a.CardType=254 THEN 1 ELSE 0 END),0) AS paperNum FROM tbstatentry a
AND a.CancelFlag = 0 AND a.RecordType&1=1 AND a.VehicleClass in(1,2,3,4,11,12,13,14,15,16,21,22,23,24,25,26) AND a.CardType IN (26,254)
AND a.StationID = #{stationId}
AND a.StaDate = #{timeFormat}
AND a.ShiftID = #{shiftId}
GROUP BY a.OperatorID

SELECT a.OperatorID AS operatorId, (SELECT OperatorName FROM dbtoms.tboperatorinfo WHERE a.OperatorID = OperatorID LIMIT 1 ) AS operatorName, IFNULL(SUM(CASE WHEN a.DealStatus&14 IN (0,10) THEN a.TotalToll ELSE 0 END),0)/100 AS toll, IFNULL(SUM(CASE WHEN a.CardType=26 THEN 1 ELSE 0 END),0) AS yjIcCardNum, IFNULL(SUM(CASE WHEN a.CardType=254 THEN 1 ELSE 0 END),0) AS paperNum FROM tbstatexit a
AND a.CancelFlag=0 AND a.RecordType&3=3 AND a.RecordType&192=0 AND substring(a.LaneID,-4,1)=0 AND substring(a.LaneID,-3,1)=1
AND a.StationID = #{stationId}
AND a.StaDate = #{timeFormat}
AND a.ShiftID = #{shiftId}
GROUP BY a.OperatorID

SELECT a.OperatorID AS operatorId, (SELECT OperatorName FROM dbtoms.tboperatorinfo WHERE a.OperatorID = OperatorID LIMIT 1 ) AS operatorName, SUM(a.addedtoll) / 100 AS toll FROM ${tableName} a
AND a.CancelFlag=0 AND a.issplit=1 AND (a.paytype IS null OR a.paytype=0)
AND a.StationID = #{stationId}
AND a.StaDate = #{timeFormat}
AND a.ShiftID = #{shiftId}
GROUP BY a.operatorid

SELECT
StationID AS stationId,
IFNULL(CAST(sum(AddedToll)/100 as DECIMAL(10,2)), 0) AS addedToll,
IFNULL(CAST(sum(HandToll)/100 as DECIMAL(10,2)), 0) AS handToll
FROM ${tableName}

    AND CancelFlag = 0
    AND StationID in

        #{stationId}


        AND StaDate = #{timeFormat}


        AND ShiftID = #{shiftId}


GROUP BY StationID
ORDER BY StationID ASC

SELECT
StationID AS stationId,
IFNULL(SUM(AddedToll),0)/100 AS extAddToll
FROM ${tableName}

    AND CancelFlag = 0
    AND IsSplit=1
    AND StationID in

        #{stationId}


        AND StaDate = #{timeFormat}


        AND ShiftID = #{shiftId}


GROUP BY StationID
ORDER BY StationID ASC

SELECT a.StationID AS stationId, (SELECT stationname FROM dbtoms.stationcode WHERE a.StationID = stationid LIMIT 1 ) AS stationName, IFNULL(SUM(CASE WHEN a.DealStatus&14=6 THEN a.CarNum ELSE 0 END),0) AS officialIcCardCount, IFNULL(SUM(CASE WHEN a.DealStatus&14=8 THEN a.CarNum ELSE 0 END),0) AS militaryIcCardCount, IFNULL(SUM(CASE WHEN a.DealStatus&14=12 THEN a.CarNum ELSE 0 END),0) AS freeIcCardCount, IFNULL(SUM(CASE WHEN (a.DealStatus&14 != 14 AND a.DealStatus&14 != 2 AND a.DealStatus&0xE00000 != 0x200000 AND a.DealStatus&0x1000000=0 AND a.DealStatus&32 != 32 AND a.CardType=0) OR (a.CardType=26 AND a.DealStatus&32 != 32) THEN a.CardNum ELSE 0 END),0) AS dueIcCardCount, IFNULL(SUM(CASE WHEN a.DealStatus&14=4 THEN a.TotalArrearage ELSE 0 END),0)/100 arrearsAmount, SUM(CASE WHEN a.PayType = 0 THEN a.TotalToll / 100 ELSE 0 END) AS dueAmount, IFNULL(CAST(SUM(CASE WHEN a.PayType=16 THEN a.TotalToll ELSE 0 END)/100 as DECIMAL(10,2)), 0) mobilePaymentAmount, IFNULL(CAST(SUM(CASE WHEN a.PayType=2 THEN a.TotalToll ELSE 0 END) /100 as DECIMAL(10,2)), 0) as ePaymentAmount FROM ${tableName} a
AND CancelFlag = 0 AND StationID in
#{stationId}
AND StaDate = #{timeFormat}
AND ShiftID = #{shiftId}
GROUP BY StationID ORDER BY StationID ASC

SELECT a.OperatorID AS operatorId, a.StationID AS stationId, (SELECT stationname FROM dbtoms.stationcode WHERE a.StationID = stationid LIMIT 1 ) AS stationName, a.StaDate AS staDate, LEFT(a.StaDate, 6) AS monthDate, IFNULL(SUM(CASE WHEN a.PayChannel=1 THEN a.CarNum ELSE 0 END),0) ylCount, IFNULL(SUM(CASE WHEN a.PayChannel=1 THEN CAST(a.TotalToll/100 as DECIMAL(10,2)) ELSE 0 END),0) ylToll, IFNULL(SUM(CASE WHEN a.PayChannel=2 THEN a.CarNum ELSE 0 END),0) wxCount, IFNULL(SUM(CASE WHEN a.PayChannel=2 THEN CAST(a.TotalToll/100 as DECIMAL(10,2)) ELSE 0 END),0) wxToll, IFNULL(SUM(CASE WHEN a.PayChannel=3 THEN a.CarNum ELSE 0 END),0) zfbCount, IFNULL(SUM(CASE WHEN a.PayChannel=3 THEN CAST(a.TotalToll/100 as DECIMAL(10,2)) ELSE 0 END),0) zfbToll, IFNULL(SUM(CASE WHEN a.PayChannel=4 THEN a.CarNum ELSE 0 END),0) bdCount, IFNULL(SUM(CASE WHEN a.PayChannel=4 THEN CAST(a.TotalToll/100 as DECIMAL(10,2)) ELSE 0 END),0) bdToll, IFNULL(SUM(CASE WHEN a.PayChannel=5 THEN a.CarNum ELSE 0 END),0) jdCount, IFNULL(SUM(CASE WHEN a.PayChannel=5 THEN CAST(a.TotalToll/100 as DECIMAL(10,2)) ELSE 0 END),0) jdToll, IFNULL(SUM(CASE WHEN a.PayChannel=32 THEN a.CarNum ELSE 0 END),0) txbCount, IFNULL(SUM(CASE WHEN a.PayChannel=32 THEN CAST(a.TotalToll/100 as DECIMAL(10,2)) ELSE 0 END),0) txbToll, IFNULL(SUM(CASE WHEN a.PayChannel=33 THEN a.CarNum ELSE 0 END),0) szrmbCount, IFNULL(SUM(CASE WHEN a.PayChannel=33 THEN CAST(a.TotalToll/100 as DECIMAL(10,2)) ELSE 0 END),0) szrmbToll, IFNULL(SUM(CASE WHEN a.PayChannel NOT IN (1,2,3,4,5,32,33) THEN a.CarNum ELSE 0 END),0) qtCount, IFNULL(SUM(CASE WHEN a.PayChannel NOT IN (1,2,3,4,5,32,33) THEN CAST(a.TotalToll/100 as DECIMAL(10,2)) ELSE 0 END),0) qtToll, IFNULL(SUM(a.CarNum),0) hjCount, IFNULL(SUM(CAST(a.TotalToll/100 as DECIMAL(10,2))),0) hjToll FROM
SELECT * FROM ${tableName}
AND PayType = 16 AND StationID in
#{stationId}
AND StaDate >= #{intBeginTime}
AND StaDate <= #{intEndTime}
a
GROUP BY StaDate
GROUP BY monthDate
GROUP BY StationID
GROUP BY OperatorID
